-- Member codes: MEM-<6-digit sequence>, generated by the database (docs/SPEC.md section 5).
CREATE SEQUENCE "member_code_seq" AS integer START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 999999 NO CYCLE;

CREATE FUNCTION next_member_code() RETURNS text
LANGUAGE sql VOLATILE
AS $$
  SELECT 'MEM-' || lpad(nextval('member_code_seq')::text, 6, '0')
$$;

